import java.util.ArrayList;
import java.util.List;

record Expense(String title, String category, double amount) {}

class ExpenseRepository {
    private final List<Expense> expenses = new ArrayList<>();

    void add(Expense expense) { expenses.add(expense); }
    double total() { return expenses.stream().mapToDouble(Expense::amount).sum(); }
    List<Expense> byCategory(String category) {
        return expenses.stream().filter(item -> item.category().equals(category)).toList();
    }
}

public class SmartSpend {
    public static void main(String[] args) {
        ExpenseRepository repository = new ExpenseRepository();
        repository.add(new Expense("Lunch", "Food", 12.5));
        System.out.println(repository.total());
    }
}
