#include <stdio.h>

#define MAX_EXPENSES 32

typedef struct {
    char title[64];
    char category[32];
    double amount;
} Expense;

double total(const Expense expenses[], size_t count) {
    double result = 0.0;
    for (size_t i = 0; i < count; ++i) result += expenses[i].amount;
    return result;
}

int main(void) {
    Expense expenses[MAX_EXPENSES] = {
        {"Lunch", "Food", 12.5},
        {"Bus", "Transport", 2.0}
    };
    printf("Total: %.2f\n", total(expenses, 2));
    return 0;
}
