```c
#include <stdio.h>
#include <string.h>

#define MAX_EXPENSES 64

typedef struct {
    int id;
    char title[64];
    char category[32];
    double amount;
} Expense;

typedef struct {
    Expense items[MAX_EXPENSES];
    size_t count;
} ExpenseRepository;

void add_expense(ExpenseRepository* repository, Expense expense) {
    if (repository->count < MAX_EXPENSES) repository->items[repository->count++] = expense;
}

double total_by_category(const ExpenseRepository* repository, const char* category) {
    double total = 0.0;
    for (size_t i = 0; i < repository->count; ++i)
        if (strcmp(repository->items[i].category, category) == 0) total += repository->items[i].amount;
    return total;
}

int main(void) {
    ExpenseRepository repository = {0};
    add_expense(&repository, (Expense){1, "Lunch", "Food", 12.5});
    add_expense(&repository, (Expense){2, "Coffee", "Food", 4.5});
    printf("Food total: %.2f\n", total_by_category(&repository, "Food"));
    return 0;
}
```
