```mermaid
flowchart TD
    start(["Enviar mensaje"]) --> validate["Validar entrada"]
    validate --> valid{"¿La solicitud es válida?"}

    valid -- "No" --> inputError["Mostrar error de entrada"]
    inputError --> idle(["En espera"])

    valid -- "Sí" --> build["Crear solicitud<br>Historial de conversación · configuración del modelo"]
    build --> gateway["Llamar a AiGateway"]
    gateway --> stream["Recibir fragmento de respuesta"]

    stream --> more{"¿Hay más fragmentos de respuesta?"}
    more -- "Sí" --> stream
    more -- "No" --> save["Guardar respuesta y actualizar interfaz"]
    save --> idle

    gateway -- "Falló la llamada" --> failure["Mostrar error y reintentar"]
    failure --> idle
```
