from dataclasses import dataclass

@dataclass
class Expense:
    title: str
    category: str
    amount: float

class ExpenseRepository:
    def __init__(self) -> None:
        self.expenses: list[Expense] = []

    def add(self, expense: Expense) -> None:
        self.expenses.append(expense)

    def total(self) -> float:
        return sum(item.amount for item in self.expenses)

    def by_category(self, category: str) -> list[Expense]:
        return [item for item in self.expenses if item.category == category]

repository = ExpenseRepository()
repository.add(Expense("Lunch", "Food", 12.5))
repository.add(Expense("Bus", "Transport", 2.0))
print(repository.by_category("Food"))
print(f"Total = {repository.total()}")
