```csharp
public sealed record Expense(int Id, string Title, string Category, decimal Amount);

public sealed class ExpenseRepository
{
    private readonly List<Expense> expenses = new();

    public void Add(Expense expense) => expenses.Add(expense);
    public decimal Total() => expenses.Sum(item => item.Amount);
    public IReadOnlyList<Expense> ByCategory(string category) =>
        expenses.Where(item => item.Category == category).ToList();
}

var repository = new ExpenseRepository();
repository.Add(new Expense(1, "Lunch", "Food", 12.5m));
repository.Add(new Expense(2, "Coffee", "Food", 4.5m));
Console.WriteLine($"Food total: {repository.ByCategory("Food").Sum(item => item.Amount):F2}");
```
